@extends('layouts.app') @section('title',$l->group_name.' · '.$l->subject_name) @section('content')<div class="mb-3"><a href="{{route('journal.today',['date'=>$l->lesson_date])}}" class="text-decoration-none">← К занятиям</a><h1 class="h4 mt-2 mb-0">{{$l->subject_name}}</h1><div class="text-secondary">{{$l->group_name}} · {{date('d.m.Y',strtotime($l->lesson_date))}} · пара {{$l->lesson_number}}</div></div>@if(auth()->user()->canDo('semester.view'))<a class="btn btn-outline-primary mb-3" href="{{route('semester.edit',[$l->study_group_id,$l->subject_id])}}">Итоги по предмету</a>@endif<div id="saveStatus" class="small text-secondary mb-2">Изменения сохраняются автоматически</div><div class="card overflow-hidden"><div class="list-group list-group-flush">@foreach($students as $s)<div class="list-group-item p-3 student-row" data-student="{{$s->id}}"><div class="fw-semibold mb-2">{{$loop->iteration}}. {{$s->last_name}} {{$s->first_name}} {{$s->middle_name}}</div><div class="d-flex flex-wrap gap-2 align-items-center">@if(auth()->user()->canDo('attendance.mark'))<div class="btn-group attendance">@foreach(['present'=>'✓','absent'=>'Н','late'=>'О','excused'=>'У','sick'=>'Б'] as $v=>$n)<button type="button" class="btn btn-sm {{$s->attendance_status===$v?'btn-primary':'btn-outline-secondary'}}" data-value="{{$v}}">{{$n}}</button>@endforeach</div>@else<span class="badge text-bg-light">{{$s->attendance_status?:'нет отметки'}}</span>@endif @if(auth()->user()->canDo('grades.mark')&&!auth()->user()->hasRole('starosta'))<div class="btn-group grades ms-auto">@foreach(['2','3','4','5'] as $v)<button type="button" class="btn btn-sm btn-outline-success" data-value="{{$v}}">{{$v}}</button>@endforeach</div>@endif</div>@if(isset($grades[$s->id]))<div class="small mt-2">Оценки: @foreach($grades[$s->id] as $g)<span class="badge text-bg-success">{{$g->value}}</span> @endforeach</div>@endif</div>@endforeach</div></div>@endsection
@push('scripts')<script>$(function(){const csrf=$('meta[name=csrf-token]').attr('content');function state(t){$('#saveStatus').text(t)}$('.attendance button').on('click',function(){let b=$(this),row=b.closest('.student-row');state('Сохраняю…');$.post('{{route('journal.attendance',$l->id)}}',{_token:csrf,student_id:row.data('student'),status:b.data('value')}).done(()=>{b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary');state('Сохранено ✓')}).fail(()=>state('Ошибка сохранения'))});$('.grades button').on('click',function(){let b=$(this),row=b.closest('.student-row');state('Сохраняю оценку…');$.post('{{route('journal.grade',$l->id)}}',{_token:csrf,student_id:row.data('student'),value:b.data('value')}).done(()=>{state('Оценка '+b.data('value')+' сохранена ✓');location.reload()}).fail(()=>state('Ошибка сохранения оценки'))});});</script>@endpush